console.log("Test 2:", minSubArrayLen(4, [1, 4, 4]));           // Expected: 1
console.log("Test 3:", minSubArrayLen(11, [1, 1, 1, 1, 1]));    // Expected: 0

module.exports = { minSubArrayLen };
