moveZeroes(t2);
console.log("Test 2:", t2); // Expected: [0]

const t3 = [1, 2, 3];
moveZeroes(t3);
console.log("Test 3:", t3); // Expected: [1, 2, 3]

module.exports = { moveZeroes };
