// APPROACH: Greedy (Sort by End Time)
// ============================================================================
/**
 * INTUITION:
 * To maximize the number of non-overlapping intervals we can keep (which minimizes
 * the number we remove), we should always pick the interval that ends *earliest*.
 * Why? Because finishing early leaves the most room for subsequent intervals.
 *
 * 1. Sort by End Time.
 * 2. Iterate: If current interval starts before the previous one ends, it's an overlap.
 *    We discard the current one (count++) because the previous one ended earlier (greedy choice).
 *
 * Time Complexity: O(N log N)
 * Space Complexity: O(log N) or O(N) depending on sort implementation.
 */
const nonOverlappingIntervals = (intervals) => {
  if (intervals.length === 0) return 0;
  let count = 0;
  let sorted = [...intervals].sort((a, b) => a[1] - b[1]);
  let prevEnd = sorted[0][1];

  for (let i = 1; i < sorted.length; i++) {
    let [start, end] = sorted[i];
    if (start < prevEnd) {
      count++;
    } else {
      prevEnd = end;
    }
  }
  return count;
};

// ============================================================================
// TEST CASES
// ============================================================================
console.log("=== Non-overlapping Intervals Tests ===\\n");

console.log(
  "Test 1:",
  nonOverlappingIntervals([
    [1, 2],
    [2, 3],
    [3, 4],
    [1, 3],
  ])
); // Expected: 1

console.log(
  "Test 2:",
  nonOverlappingIntervals([
    [1, 2],
    [1, 2],
    [1, 2],
  ])
); // Expected: 2

module.exports = { nonOverlappingIntervals };
`,Ux=`// ============================================================================
// APPROACH: Backtracking
// ============================================================================
/**
 * INTUITION:
 * We need to place one queen per row.
 * For each row, we try placing a queen in every column (0 to n-1).
 * Before placing, we check if the position is under attack.
 *
 * A position (r, c) is under attack if:
 * 1. Another queen is in the same column \`c\`.
 * 2. Another queen is on the same positive diagonal (r + c = constant).
 * 3. Another queen is on the same negative diagonal (r - c = constant).
 *
 * We use Sets to keep track of occupied columns and diagonals for O(1) lookups.
 *
 * Time Complexity: O(N!) - The first queen has N choices, the second N-2 (approx), etc.
 * Space Complexity: O(N^2) - To store the board state (and O(N) for recursion/sets).
 */
const nQueen = (n) => {
  const cols = new Set();
  const negDiagonal = new Set();
  const posDiagonal = new Set();

  const res = [];

  // Initialize n x n board with '.'
  const board = Array.from({ length: n }, () => Array(n).fill("."));

  const backTrack = (row) => {
    // Base Case: If we've placed queens in all rows (0 to n-1), we found a solution
    if (row === n) {
      res.push(board.map((item) => item.join("")));
      return;
    }

    // Try placing queen in each column of the current row
    for (let col = 0; col < n; col++) {
      // Check if placing queen here is valid
      if (
        cols.has(col) ||
        negDiagonal.has(row - col) ||
        posDiagonal.has(row + col)
      )
        continue;

      // Choose (Place Queen)
      board[row][col] = "Q";
      cols.add(col);
      negDiagonal.add(row - col);
      posDiagonal.add(row + col);

      // Explore (Next Row)
      backTrack(row + 1);

      // Unchoose (Backtrack)
      board[row][col] = ".";
      cols.delete(col);
      negDiagonal.delete(row - col);
      posDiagonal.delete(row + col);
    }
  };

  backTrack(0);
  return res;
};

// ============================================================================
// TEST CASES
// ============================================================================
console.log("=== N-Queens Tests ===\\n");
console.log("Test 1 (n=4):", nQueen(4));
// Expected: [[".Q..","...Q","Q...","..Q."],["..Q.","Q...","...Q",".Q.."]]

console.log("Test 2 (n=1):", nQueen(1));
// Expected: [["Q"]]

module.exports = { nQueen };
