console.log(hasPathSum(t, 26)); // true  5+8+13
console.log(hasPathSum(new TreeNode(1, new TreeNode(2)), 1)); // false -- 1 is not a leaf
console.log(hasPathSum(null, 0)); // false
`,ov=`/**
 * ============================================================================
 * APPROACH: Dijkstra / Priority Queue (Minimize the Maximum Edge)
 * ============================================================================
 *
 * INTUITION:
 *
 * This is a shortest-path problem with a NON-STANDARD cost definition.
 *
 * - Moving between two adjacent cells has a "cost":
 *     |height[current] - height[next]|
 * - The total cost of a path is NOT the sum of costs,
 *   but the MAXIMUM cost encountered along the path.
 *
 * Key Observation:
 * - As we extend a path, the effort (max edge so far) NEVER decreases.
 * - This monotonic property allows Dijkstra’s algorithm to work.
 *
 * Instead of minimizing SUM of edges, we minimize:
 *
 *   max(edge_1, edge_2, ..., edge_k)
 *
 * ---------------------------------------------------------------------------
 * STATE:
 *
 * - Each cell (r, c) is a node
 * - lowestEffort[row][col] = minimum possible effort to reach (row, col)
 *
 * ---------------------------------------------------------------------------
 * EDGE RELAXATION:
 *
 * From (r, c) → (nr, nc):
 *
 *   edgeEffort = |heights[r][c] - heights[nr][nc]|
 *   worstStepSoFar = max(effortSoFar, stepEffort)
 *
 * If worstStepSoFar < lowestEffort[nextRow][nextCol], update it.
 *
 * ---------------------------------------------------------------------------
 * ALGORITHM:
 *
 * 1. Initialize lowestEffort[][] with Infinity
 * 2. lowestEffort[0][0] = 0
 * 3. Push (0, 0, 0) into min-heap → [effort, row, col]
 * 4. While heap is not empty:
 *    a. Pop cell with minimum effort so far
 *    b. If it is destination, return effort
 *    c. Relax all valid neighbors
 *
 * ---------------------------------------------------------------------------
 * TIME COMPLEXITY:
 *
 * - Each cell is processed at most once with its best effort
 * - Heap operations: O(log(R * C))
 *
 * Total: O(R * C * log(R * C))
 *
 * ---------------------------------------------------------------------------
 * SPACE COMPLEXITY:
 *
 * - dist array: O(R * C)
 * - priority queue: O(R * C)
 *
 * ============================================================================
 */

// ============================================================================
// Binary heap ordered by a comparator. Written out here because these files are
// meant to run standalone under Node -- LeetCode's built-in PriorityQueue
// exists only inside their judge, so depending on it leaves the file unrunnable.
// ============================================================================
class BinaryHeap {
  /** compare(a, b) < 0 means \`a\` comes out first. */
  constructor(compare) {
    this.items = [];
    this.compare = compare;
  }

  get size() {
    return this.items.length;
  }

  push(entry) {
    this.items.push(entry);
    let index = this.items.length - 1;

    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (this.compare(this.items[parent], this.items[index]) <= 0) break;
      [this.items[parent], this.items[index]] = [this.items[index], this.items[parent]];
      index = parent;
    }
  }

  pop() {
    if (this.items.length === 0) return undefined;

    const top = this.items[0];
    const last = this.items.pop();

    if (this.items.length > 0) {
      this.items[0] = last;
      let index = 0;

      for (;;) {
        const left = 2 * index + 1;
        const right = left + 1;
        let best = index;

        if (left < this.items.length && this.compare(this.items[left], this.items[best]) < 0) best = left;
        if (right < this.items.length && this.compare(this.items[right], this.items[best]) < 0) best = right;
        if (best === index) break;

        [this.items[best], this.items[index]] = [this.items[index], this.items[best]];
        index = best;
      }
    }

    return top;
  }
}

/**
 * @param {number[][]} heights grid of cell elevations
 * @return {number} the smallest possible "worst single step" along some path
 *   from the top-left cell to the bottom-right one
 */
const pathWithMinimumEffort = (heights) => {
  const rowCount = heights.length;
  const colCount = heights[0].length;

  // lowestEffort[row][col] = best "worst step" seen for reaching that cell.
  const lowestEffort = Array.from({ length: rowCount }, () => Array(colCount).fill(Infinity));

  // Entries are [effortSoFar, row, col], smallest effort first.
  const frontier = new BinaryHeap((a, b) => a[0] - b[0]);

  lowestEffort[0][0] = 0;
  frontier.push([0, 0, 0]);

  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

  while (frontier.size > 0) {
    const [effortSoFar, row, col] = frontier.pop();

    // Smallest-first order means the first arrival is already optimal.
    if (row === rowCount - 1 && col === colCount - 1) return effortSoFar;

    // A gentler route to this cell was queued later; this entry is stale.
    if (effortSoFar > lowestEffort[row][col]) continue;

    for (const [rowDelta, colDelta] of directions) {
      const nextRow = row + rowDelta;
      const nextCol = col + colDelta;

      if (nextRow < 0 || nextCol < 0 || nextRow >= rowCount || nextCol >= colCount) continue;

      const stepEffort = Math.abs(heights[row][col] - heights[nextRow][nextCol]);

      // The cost of a path is its WORST step, not the sum of its steps -- so
      // costs combine with max(), not +. That single change is what turns
      // Dijkstra into a minimax-path search.
      const worstStepSoFar = Math.max(effortSoFar, stepEffort);

      if (worstStepSoFar < lowestEffort[nextRow][nextCol]) {
        lowestEffort[nextRow][nextCol] = worstStepSoFar;
        frontier.push([worstStepSoFar, nextRow, nextCol]);
      }
    }
  }

  return 0; // a 1x1 grid never enters the loop body past the first pop
};

// ============================================================================
// TEST CASES
// ============================================================================
console.log("=== Path With Minimum Effort Tests ===\\n");

console.log("Test 1:", pathWithMinimumEffort([[1, 2, 2], [3, 8, 2], [5, 3, 5]])); // Expected: 2
console.log("Test 2:", pathWithMinimumEffort([[1, 2, 3], [3, 8, 4], [5, 3, 5]])); // Expected: 1
console.log("Test 3:", pathWithMinimumEffort([
  [1, 2, 1, 1, 1],
  [1, 2, 1, 2, 1],
  [1, 2, 1, 2, 1],
  [1, 2, 1, 2, 1],
  [1, 1, 1, 2, 1],
])); // Expected: 0
console.log("Test 4:", pathWithMinimumEffort([[1]]));            // Expected: 0 (single cell)
console.log("Test 5:", pathWithMinimumEffort([[1, 10]]));        // Expected: 9 (forced single step)

module.exports = { pathWithMinimumEffort, BinaryHeap };
`,sv=`// ============================================================================
// APPROACH: Fixed Sliding Window
// ============================================================================
/**
 * INTUITION:
 * We need to find a substring in s2 of length \`s1.length\` that has the exact
 * same character counts as s1.
 * We maintain a window of size \`s1.length\` on s2.
 * We compare the frequency arrays (or maps) of s1 and the current window in s2.
 *
 * DRY RUN:
 * Input: s1 = "ab", s2 = "eidbaooo"
 * s1 length = 2. Target counts: {a:1, b:1}
 *
 * 1. Init Window (indices 0-1): "ei"
 *    - s2 counts: {e:1, i:1}. Match? No.
 *
 * 2. Slide (index 2): Add 'd', Remove 'e'
 *    - Window: "id". s2 counts: {i:1, d:1}. Match? No.
 *
 * 3. Slide (index 3): Add 'b', Remove 'i'
 *    - Window: "db". s2 counts: {d:1, b:1}. Match? No.
 *
 * 4. Slide (index 4): Add 'a', Remove 'd'
 *    - Window: "ba". s2 counts: {b:1, a:1}. Match? Yes!
 *    - Return true.
 *
 * Time Complexity: O(N) where N is length of s2.
 * Space Complexity: O(1) (Array of size 26).
 */
const checkInclusion = (s1, s2) => {
  if (s1.length > s2.length) return false;

  const need = new Map();
  const window = new Map();

  // build frequency map for s1
  for (const ch of s1) {
    need.set(ch, (need.get(ch) || 0) + 1);
  }

  // build first window
  for (let i = 0; i < s1.length; i++) {
    const ch = s2[i];
    window.set(ch, (window.get(ch) || 0) + 1);
  }

  if (mapsEqual(need, window)) return true;

  // slide the window
  for (let i = s1.length; i < s2.length; i++) {
    // add right char
    const rightChar = s2[i];
    window.set(rightChar, (window.get(rightChar) || 0) + 1);

    // remove left char
    const leftChar = s2[i - s1.length];
    window.set(leftChar, window.get(leftChar) - 1);

    if (mapsEqual(need, window)) return true;
  }

  return false;
};

function mapsEqual(m1, m2) {
  if (m1.size !== m2.size) return false;
  for (const [key, val] of m1) {
    if (m2.get(key) !== val) return false;
  }
  return true;
}

console.log("=== Permutation in String Tests ===\\n");
console.log("Test 1:", checkInclusion("ab", "eidbaooo")); // Expected: true
console.log("Test 2:", checkInclusion("ab", "eidboaoo")); // Expected: false
console.log("Test 3:", checkInclusion("abc", "bbbca")); // Expected: true

module.exports = { checkInclusion };
`,av=`// ============================================================================
// APPROACH: Backtracking with a \`used\` array + sort-and-skip dedup
// ============================================================================
/**
 * STORY / INTUITION:
 * This is \`permutations.js\` (LC46) plus ONE extra rule to avoid generating
 * the same permutation twice when duplicate values exist.
 *
 * SORT the array first — this makes duplicate values sit next to each other.
 * At each recursion level, we're choosing "what goes in this slot next."
 * If two candidates have the SAME VALUE, picking either one leads to the
 * exact same set of future permutations — so only let ONE of them go first.
 *
 * The rule: skip \`nums[i]\` if \`nums[i] === nums[i-1]\` AND \`nums[i-1]\` is
 * NOT currently used. "Not used" means the earlier duplicate is sitting on
 * the bench, available for THIS slot too — so this branch is a redundant
 * copy of the branch where the earlier duplicate gets picked instead.
 *
 * DRY RUN: nums = [1,1,2]  (sorted: [1,1,2], indices 0,1,2)
 *
 * Slot 1:
 *   i=0 (val=1, unused): pick → current=[1], used=[T,F,F]
 *     Slot 2:
 *       i=1 (val=1, unused, prev(i=0) IS used → don't skip): pick → [1,1]
 *         Slot 3: i=2 (val=2) → [1,1,2] ✓ COMPLETE
 *       i=2 (val=2, unused): pick → [1,2]
 *         Slot 3: i=1 (val=1, prev(i=0) IS used → don't skip) → [1,2,1] ✓ COMPLETE
 *   i=1 (val=1, unused, prev(i=0) NOT used → SKIP — redundant with i=0 above)
 *   i=2 (val=2, unused): pick → current=[2], used=[F,F,T]
 *     Slot 2:
 *       i=0 (val=1, unused) → [2,1]
 *         Slot 3: i=1 (val=1, prev(i=0) IS used → don't skip) → [2,1,1] ✓ COMPLETE
 *       i=1 (val=1, unused, prev(i=0) NOT used → SKIP)
 *
 * Result: [[1,1,2],[1,2,1],[2,1,1]] ✓
 *
 * Time:  O(N! * N) — generating all permutations, each of length N
 * Space: O(N) — recursion depth + \`used\` array
 */
const permuteUnique = (nums) => {
  const result = [];
  const sorted = [...nums].sort((a, b) => a - b);
  const used = new Array(sorted.length).fill(false);
  const current = [];

  const backtrack = () => {
    if (current.length === sorted.length) {
      result.push([...current]);
      return;
    }

    for (let i = 0; i < sorted.length; i++) {
      if (used[i]) continue;

      // Skip a duplicate value if its earlier twin is still "on the bench" -
      // that twin will cover this exact branch in its own turn.
      if (i > 0 && sorted[i] === sorted[i - 1] && !used[i - 1]) continue;

      used[i] = true;
      current.push(sorted[i]);

      backtrack();

      current.pop();
      used[i] = false;
    }
  };

  backtrack();
  return result;
};

// ============================================================================
// TEST CASES
// ============================================================================
console.log("=== Permutations II Tests ===\\n");

console.log("Test 1:", JSON.stringify(permuteUnique([1, 1, 2])));
// Expected: [[1,1,2],[1,2,1],[2,1,1]]

console.log("Test 2:", JSON.stringify(permuteUnique([1, 2, 3])));
// Expected: 6 permutations of [1,2,3]

console.log("Test 3:", JSON.stringify(permuteUnique([1, 1, 1])));
// Expected: [[1,1,1]] (only one unique permutation)

module.exports = { permuteUnique };
`,lv=`// ============================================================================
// APPROACH: Backtracking (Swapping)
// ============================================================================
/**
 * INTUITION:
 * To generate all permutations, we can fix one number at the current position
 * and recursively permute the remaining positions.
 * We can do this in-place by swapping elements to place them in the "current"
 * position, recursing, and then swapping back (backtracking) to restore the state.
 *
 * Time Complexity: O(N * N!) - There are N! permutations, and copying takes O(N).
 * Space Complexity: O(N) - Recursion stack.
 */
var permute = function (nums) {
  const result = [];
  const curr = [];
  const used = new Array(nums.length).fill(false);

  const backtrack = () => {
    // base case: permutation complete
    if (curr.length === nums.length) {
      result.push([...curr]);
      return;
    }

    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;

      // choose
      used[i] = true;
      curr.push(nums[i]);

      // explore
      backtrack();

      // un-choose
      curr.pop();
      used[i] = false;
    }
  };

  backtrack();
  return result;
};

// ============================================================================
// TEST CASES
// ============================================================================
console.log("=== Permutations Tests ===\\n");
console.log("Test 1:", permute([1, 2, 3]));

module.exports = { permute };
`,cv=`// ============================================================================
// APPROACH: Binary Exponentiation (Iterative)
// ============================================================================
/**
 * INTUITION:
 * Instead of multiplying x by itself n times (which is O(n)), we can use
 * "Exponentiation by Squaring".
 *
 * The idea is:
 * x^n = (x^2)^(n/2)      if n is even
 * x^n = x * (x^2)^((n-1)/2)  if n is odd
 *
 * By squaring the base (x = x * x) and halving the exponent (n = n / 2) at
 * each step, we reduce the problem size logarithmically.
 *
 * Time Complexity: O(log n) - We halve n at every step.
 * Space Complexity: O(1) - We only use a few variables for storage.
 */
const pow = (x, n) => {
  if (n === 0) return 1;

  // Handle negative exponent: x^-n = (1/x)^n
  if (n < 0) {
    x = 1 / x;
    n = -n;
  }

  let result = 1;

  while (n > 0) {
    // If n is odd, multiply the current result by the current base x
    if (n % 2 === 1) {
      result *= x;
    }

    // Square the base and halve the exponent
    x = x * x;
    n = Math.floor(n / 2);
  }

  return result;
};

// ============================================================================
// TEST CASES
// ============================================================================
console.log("=== Pow(x, n) Tests ===\\n");
console.log("Test 1 (2^10):", pow(2.0, 10)); // Expected: 1024
console.log("Test 2 (2.1^3):", pow(2.1, 3)); // Expected: ~9.261
console.log("Test 3 (2^-2):", pow(2.0, -2)); // Expected: 0.25

module.exports = { pow };
