// APPROACH: Array-Backed Binary Heap (Bubble Up / Bubble Down)
// ============================================================================
/**
 * STORY / INTUITION:
 * Store the heap as a flat array where node \`i\`'s children live at \`2i+1\`
 * and \`2i+2\`, and its parent at \`floor((i-1)/2)\` — no pointers needed.
 *
 * push(x): append x at the end, then BUBBLE UP — repeatedly swap with its
 * parent while x has higher priority than the parent (per \`compare\`).
 *
 * pop(): the root (index 0) is always the highest-priority element. Replace
 * it with the LAST element, shrink the array, then BUBBLE DOWN — repeatedly
 * swap with whichever child has higher priority, until the heap property
 * holds again.
 *
 * The \`compare\` function is the ONLY thing that changes between a min-heap
 * and a max-heap — the bubble up/down mechanics are identical. This is the
 * generic building block reused conceptually by findKthLargest,
 * kClosestPointsToOrigin, mergeKSortedLists, etc.
 *
 * DRY RUN (Min Heap, compare = (a,b) => a < b):
 * push(5) -> [5]
 * push(3) -> [5,3] -> 3<5, bubble up -> [3,5]
 * push(8) -> [3,5,8] -> 8<3? no, stays -> [3,5,8]
 * push(1) -> [3,5,8,1] -> 1<5(parent idx1)? yes, swap -> [3,1,8,5]
 *                       -> 1<3(parent idx0)? yes, swap -> [1,3,8,5]
 * pop() -> return 1. Move last (5) to root -> [5,3,8]
 *          bubble down: children of 5 are 3,8; smallest child=3 <5? yes, swap -> [3,5,8]
 *          children of idx1(5): none in range -> done. Returns 1.
 * pop() -> return 3. Move last (8) to root -> [8,5]
 *          bubble down: child 5 < 8? yes, swap -> [5,8]. Returns 3.
 *
 * Time:  O(log n) for push/pop, O(1) for peek/size
 * Space: O(n) — the underlying array
 */
class PriorityQueue {
  constructor(compare = (a, b) => a < b) {
    this.heap = [];
    this.compare = compare; // return true if a has higher priority than b
  }

  size() {
    return this.heap.length;
  }

  peek() {
    // Return the root element without removing it
    return this.heap[0] ?? null;
  }

  push(x) {
    // Add new element to the end of the array
    this.heap.push(x);
    // Restore heap property by bubbling up from the last position
    this._bubbleUp(this.heap.length - 1);
  }

  pop() {
    if (this.heap.length === 0) return null;

    const top = this.heap[0]; // Store the root (highest priority)
    const last = this.heap.pop(); // Remove the last element

    if (this.heap.length > 0) {
      this.heap[0] = last; // Move the last element to the root
      this._bubbleDown(0); // Restore heap property by bubbling down
    }
    return top;
  }

  _bubbleUp(i) {
    while (i > 0) {
      const p = Math.floor((i - 1) / 2); // Parent index
      // If current element does not have higher priority than parent, stop
      if (!this.compare(this.heap[i], this.heap[p])) break;
      // Swap with parent
      [this.heap[i], this.heap[p]] = [this.heap[p], this.heap[i]];
      i = p; // Move up to parent's index
    }
  }

  _bubbleDown(i) {
    const n = this.heap.length;
    while (true) {
      let best = i; // Assume current is the highest priority among itself and children
      const l = 2 * i + 1; // Left child index
      const r = 2 * i + 2; // Right child index

      // Compare with left child
      if (l < n && this.compare(this.heap[l], this.heap[best])) best = l;
      // Compare with right child
      if (r < n && this.compare(this.heap[r], this.heap[best])) best = r;

      if (best === i) break; // Heap property satisfied
      // Swap with the higher priority child
      [this.heap[i], this.heap[best]] = [this.heap[best], this.heap[i]];
      i = best; // Continue bubbling down
    }
  }
}

// ============================================================================
// TEST CASES
// ============================================================================
console.log("=== Priority Queue Tests ===\\n");

const minHeap = new PriorityQueue((a, b) => a < b);
[5, 3, 8, 1].forEach((x) => minHeap.push(x));
console.log("Test 1 (min-heap pops):", [minHeap.pop(), minHeap.pop(), minHeap.pop(), minHeap.pop()]); // Expected: [1,3,5,8]

const maxHeap = new PriorityQueue((a, b) => a > b);
[5, 3, 8, 1].forEach((x) => maxHeap.push(x));
console.log("Test 2 (max-heap pops):", [maxHeap.pop(), maxHeap.pop(), maxHeap.pop(), maxHeap.pop()]); // Expected: [8,5,3,1]

const peekHeap = new PriorityQueue((a, b) => a < b);
peekHeap.push(10);
peekHeap.push(4);
console.log("Test 3 (peek then size):", peekHeap.peek(), peekHeap.size()); // Expected: 4 2

module.exports = { PriorityQueue };
