class TreeNode {
  constructor(val = 0, left = null, right = null) {
    this.val = val;
    this.left = left;
    this.right = right;
  }
}

/**
 * Encodes a tree to a single string.
 * @param {TreeNode} root
 * @return {string}
 */
const serialize = (root) => {
  const res = [];

  const dfs = (node) => {
    if (!node) {
      res.push("N"); // Mark null nodes
      return;
    }
    res.push(node.val); // Pre-order: process node first
    dfs(node.left); // Then left subtree
    dfs(node.right); // Then right subtree
  };

  dfs(root);
  return res.join(",");
};

/**
 * Decodes your encoded data to tree.
 * @param {string} data
 * @return {TreeNode}
 */
const deserialize = (data) => {
  const values = data.split(",");
  let i = 0;

  function dfs() {
    if (values[i] === "N") {
      i++;
      return null;
    }

    const node = new TreeNode(Number(values[i]));
    i++;
    node.left = dfs(); // Reconstruct left subtree
    node.right = dfs(); // Reconstruct right subtree
    return node;
  }

  return dfs();
};

// ============================================================================
// SAMPLE TEST CASES
// ============================================================================

// Helper function to build tree from array
function buildTree(arr) {
  if (!arr || arr.length === 0 || arr[0] === null) return null;

  const root = new TreeNode(arr[0]);
  const queue = [root];
  let i = 1;

  while (queue.length > 0 && i < arr.length) {
    const node = queue.shift();

    if (i < arr.length && arr[i] !== null) {
      node.left = new TreeNode(arr[i]);
      queue.push(node.left);
    }
    i++;

    if (i < arr.length && arr[i] !== null) {
      node.right = new TreeNode(arr[i]);
      queue.push(node.right);
    }
    i++;
  }

  return root;
}

// Helper to print tree for verification
function printTree(root) {
  if (!root) return "[]";
  const result = [];
  const queue = [root];

  while (queue.length > 0) {
    const node = queue.shift();
    if (node) {
      result.push(node.val);
      queue.push(node.left);
      queue.push(node.right);
    } else {
      result.push(null);
    }
  }

  // Remove trailing nulls
  while (result[result.length - 1] === null) {
    result.pop();
  }

  return JSON.stringify(result);
}

// Test Case 1:
//         1
//        / \\
//       2   3
//          / \\
//         4   5
