  if (rows === 1 && cols === 1) return 0;

  // visited[r][c][remainingK]
  const visited = Array.from({ length: rows }, () =>
    Array.from({ length: cols }, () => Array(k + 1).fill(false)),
  );

  const directions = [
    [1, 0],
    [-1, 0],
    [0, 1],
    [0, -1],
  ];
