console.log("Test 2:", twoCitySchedCost([[259, 770], [448, 54], [926, 667], [184, 139], [840, 118], [577, 469]])); // Expected: 1859
console.log("Test 3:", twoCitySchedCost([[10, 20], [30, 40]]));   // Expected: 50 (10 + 40)
console.log("Test 4:", twoCitySchedCost([[5, 5], [5, 5]]));       // Expected: 10 (ties)

