// Test 3: Shortest path choice
// hit -> hot -> dot -> dog -> cog (5)
// hit -> hot -> lot -> log -> cog (5)
console.log(
  "Test 3:",
  wordLadder("hit", "cog", ["hot", "dot", "dog", "lot", "log", "cog"])
);
// Expected: 5

module.exports = { wordLadder };
